const recentGroupSenders = `-- name: RecentGroupSenders :many
SELECT DISTINCT t.from_id::uuid FROM (
  SELECT g.from_id FROM GroupMessage g
  WHERE g.group_id = $1
    AND (g.created_at, g.id) <= (SELECT m.created_at, m.id FROM GroupMessage m WHERE m.id = $2::uuid)
  ORDER BY g.created_at DESC, g.id DESC
  LIMIT 50
) t WHERE t.from_id IS NOT NULL
`

type RecentGroupSendersParams struct {
	GroupID pgtype.UUID
	MsgID   uuid.UUID
}

// who sent the last 50 messages up to and including msg_id: the people a
// read marker at msg_id gives "read" ticks to
func (q *Queries) RecentGroupSenders(ctx context.Context, arg RecentGroupSendersParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, recentGroupSenders, arg.GroupID, arg.MsgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var t_from_id uuid.UUID
		if err := rows.Scan(&t_from_id); err != nil {
			return nil, err
		}
		items = append(items, t_from_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchGroupMessages = `-- name: SearchGroupMessages :many
SELECT g.id, g.content, g.from_id, g.group_id, g.created_at FROM GroupMessage g
JOIN member_table mt ON mt.group_id = g.group_id AND mt.member_id = $1::uuid
WHERE g.searchable AND g.deleted_at IS NULL
  AND lower(g.content) LIKE '%' || $2::text || '%' ESCAPE '\'
  AND g.created_at >= mt.joined_at
  AND ($3::uuid IS NULL OR g.group_id = $3::uuid)
  AND (g.created_at, g.id) < ($4::timestamp, $5::uuid)
  AND ($6::timestamp IS NULL OR g.created_at >= $6::timestamp)
ORDER BY g.created_at DESC, g.id DESC
LIMIT $7
`

type SearchGroupMessagesParams struct {
	Me       uuid.UUID
	Q        string
	InGroup  pgtype.UUID
	BeforeAt pgtype.Timestamp
	BeforeID uuid.UUID
	AfterAt  pgtype.Timestamp
	Lim      int32
}

type SearchGroupMessagesRow struct {
	ID        uuid.UUID
	Content   pgtype.Text
	FromID    pgtype.UUID
	GroupID   pgtype.UUID
	CreatedAt pgtype.Timestamp
}

// searchable messages of my groups containing q, sent since I joined
func (q *Queries) SearchGroupMessages(ctx context.Context, arg SearchGroupMessagesParams) ([]SearchGroupMessagesRow, error) {
	rows, err := q.db.Query(ctx, searchGroupMessages,
		arg.Me,
		arg.Q,
		arg.InGroup,
		arg.BeforeAt,
		arg.BeforeID,
		arg.AfterAt,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchGroupMessagesRow
	for rows.Next() {
		var i SearchGroupMessagesRow
		if err := rows.Scan(
			&i.ID,
			&i.Content,
			&i.FromID,
			&i.GroupID,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchPrivateMessages = `-- name: SearchPrivateMessages :many
SELECT m.id, m.content, m.from_id, m.to_id, m.created_at FROM message m
WHERE (m.from_id = $1::uuid OR m.to_id = $1::uuid)
  AND m.deleted_at IS NULL
  AND lower(m.content) LIKE '%' || $2::text || '%' ESCAPE '\'
  AND ($3::uuid IS NULL
       OR (m.from_id = $1::uuid AND m.to_id = $3::uuid)
       OR (m.to_id = $1::uuid AND m.from_id = $3::uuid))
  AND (m.created_at, m.id) < ($4::timestamp, $5::uuid)
  AND ($6::timestamp IS NULL OR m.created_at >= $6::timestamp)
ORDER BY m.created_at DESC, m.id DESC
LIMIT $7
`

type SearchPrivateMessagesParams struct {
	Me       uuid.UUID
	Q        string
	WithUser pgtype.UUID
	BeforeAt pgtype.Timestamp
	BeforeID uuid.UUID
	AfterAt  pgtype.Timestamp
	Lim      int32
}

type SearchPrivateMessagesRow struct {
	ID        uuid.UUID
	Content   pgtype.Text
	FromID    pgtype.UUID
	ToID      pgtype.UUID
	CreatedAt pgtype.Timestamp
}

// my private messages containing q (lower-cased, LIKE-escaped), newest
// first, optionally with one person, older than the cursor
func (q *Queries) SearchPrivateMessages(ctx context.Context, arg SearchPrivateMessagesParams) ([]SearchPrivateMessagesRow, error) {
	rows, err := q.db.Query(ctx, searchPrivateMessages,
		arg.Me,
		arg.Q,
		arg.WithUser,
		arg.BeforeAt,
		arg.BeforeID,
		arg.AfterAt,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchPrivateMessagesRow
	for rows.Next() {
		var i SearchPrivateMessagesRow
		if err := rows.Scan(
			&i.ID,
			&i.Content,
			&i.FromID,
			&i.ToID,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
